import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseVersion } from './versions.js';
export const PACKAGE_NAME = '@sanity/ui';
export const LEGACY_COEXISTENCE_HINT = 'To add v5 alongside an existing @sanity/ui install, use a package alias — see the README section "For apps using Sanity UI v3".';
/**
 * Framework ids map 1:1 to the `framework` field written into sanity-ui.json.
 * Each carries the ordered list of candidate entry files where the stylesheet
 * import belongs.
 */
const FRAMEWORK_ENTRIES = {
    'next-app': ['app/layout.tsx', 'app/layout.jsx', 'src/app/layout.tsx', 'src/app/layout.jsx'],
    'next-pages': ['pages/_app.tsx', 'pages/_app.jsx', 'src/pages/_app.tsx', 'src/pages/_app.jsx'],
    'react-router': ['app/root.tsx', 'app/root.jsx'],
    'remix': ['app/root.tsx', 'app/root.jsx'],
    'vite': ['src/main.tsx', 'src/main.jsx', 'src/main.ts'],
    'astro': [],
    'react': ['src/index.tsx', 'src/main.tsx', 'src/index.jsx', 'src/main.jsx'],
};
export function readPackageJson(cwd) {
    const file = join(cwd, 'package.json');
    if (!existsSync(file))
        return null;
    try {
        return JSON.parse(readFileSync(file, 'utf8'));
    }
    catch {
        return null;
    }
}
export function allDeps(pkg) {
    if (!pkg)
        return {};
    return { ...pkg.dependencies, ...pkg.devDependencies, ...pkg.peerDependencies };
}
export function detectPackageManager(cwd) {
    if (existsSync(join(cwd, 'bun.lockb')) || existsSync(join(cwd, 'bun.lock')))
        return 'bun';
    if (existsSync(join(cwd, 'pnpm-lock.yaml')))
        return 'pnpm';
    if (existsSync(join(cwd, 'yarn.lock')))
        return 'yarn';
    if (existsSync(join(cwd, 'package-lock.json')))
        return 'npm';
    const declared = readPackageJson(cwd)?.packageManager;
    if (typeof declared === 'string') {
        const name = declared.split('@')[0];
        if (name === 'pnpm' || name === 'yarn' || name === 'npm' || name === 'bun')
            return name;
    }
    return 'npm';
}
export function detectFramework(cwd, pkg = readPackageJson(cwd)) {
    const deps = allDeps(pkg);
    const has = (name) => Boolean(deps[name]);
    const dir = (relative) => existsSync(join(cwd, relative));
    if (has('next')) {
        if (dir('app') || dir('src/app'))
            return 'next-app';
        if (dir('pages') || dir('src/pages'))
            return 'next-pages';
        return 'next-app';
    }
    if (has('@remix-run/react') || has('@remix-run/dev'))
        return 'remix';
    if (has('@react-router/dev') || has('react-router'))
        return 'react-router';
    if (has('astro'))
        return 'astro';
    if (has('vite'))
        return 'vite';
    return 'react';
}
export function detectTypeScript(cwd, pkg = readPackageJson(cwd)) {
    return existsSync(join(cwd, 'tsconfig.json')) || Boolean(allDeps(pkg)['typescript']);
}
/**
 * Returns the first existing candidate entry file, otherwise the first
 * candidate as the place to create one. Astro has no fixed entry, so we look
 * for a layout component.
 */
export function detectEntry(cwd, framework) {
    if (framework === 'astro')
        return detectAstroLayout(cwd);
    const candidates = FRAMEWORK_ENTRIES[framework];
    const existing = candidates.find((rel) => existsSync(join(cwd, rel)));
    return { entry: existing ?? candidates[0] ?? 'src/index.tsx', exists: Boolean(existing) };
}
function detectAstroLayout(cwd) {
    const candidates = [
        'src/layouts/Layout.astro',
        'src/layouts/BaseLayout.astro',
        'src/layouts/index.astro',
        'src/pages/index.astro',
    ];
    const existing = candidates.find((rel) => existsSync(join(cwd, rel)));
    return { entry: existing ?? candidates[0] ?? 'src/layouts/Layout.astro', exists: Boolean(existing) };
}
/**
 * Resolves the installed React version from node_modules, falling back to the
 * declared range in package.json (carets/tildes stripped).
 */
export function detectReactVersion(cwd, pkg = readPackageJson(cwd)) {
    const installed = readInstalledVersion(cwd, 'react');
    if (installed)
        return { version: installed, source: 'installed' };
    const declared = allDeps(pkg)['react'];
    if (typeof declared === 'string') {
        return { version: declared.replace(/^[\^~>=<\s]+/, ''), source: 'declared' };
    }
    return { version: null, source: 'missing' };
}
function readInstalledVersion(cwd, name) {
    const file = join(cwd, 'node_modules', name, 'package.json');
    if (!existsSync(file))
        return null;
    try {
        const pkg = JSON.parse(readFileSync(file, 'utf8'));
        return pkg.version ?? null;
    }
    catch {
        return null;
    }
}
export function isPackageInstalled(cwd, name) {
    return existsSync(join(cwd, 'node_modules', name, 'package.json'));
}
export function readInstalledPackageVersion(cwd, name) {
    return readInstalledVersion(cwd, name);
}
export function isLegacyUiVersion(version) {
    const major = parseVersion(version)?.[0];
    return major !== undefined && major < 5;
}
function detectAliasedInstall(deps) {
    for (const [name, spec] of Object.entries(deps)) {
        if (typeof spec === 'string' && /^npm:@sanity\/ui@(5(?:\..*)?|alpha)$/.test(spec))
            return name;
    }
    return null;
}
/** Reads the major from a declared range, skipping workspace/catalog/link specs. */
function declaredMajor(spec) {
    if (typeof spec !== 'string')
        return null;
    if (/^(workspace:|catalog:|link:|file:)/.test(spec))
        return null;
    const npmAlias = spec.match(/^npm:@sanity\/ui@(\d+)/);
    if (npmAlias)
        return Number(npmAlias[1]);
    return parseVersion(spec.replace(/^[\^~>=<\s]+/, ''))?.[0] ?? null;
}
function detectLegacyInstall(cwd, deps) {
    const installed = readInstalledPackageVersion(cwd, PACKAGE_NAME);
    if (installed && isLegacyUiVersion(installed)) {
        return installed;
    }
    const declared = deps[PACKAGE_NAME];
    const major = declaredMajor(declared);
    if (major !== null && major < 5) {
        return declared ?? 'unknown';
    }
    return null;
}
export function detect(cwd) {
    const pkg = readPackageJson(cwd);
    const deps = allDeps(pkg);
    const framework = detectFramework(cwd, pkg);
    const entry = detectEntry(cwd, framework);
    const typescript = detectTypeScript(cwd, pkg) || (entry.exists && /\.tsx?$/.test(entry.entry));
    return {
        pkg,
        packageManager: detectPackageManager(cwd),
        framework,
        typescript,
        ...entry,
        react: detectReactVersion(cwd, pkg),
        aliasedInstall: detectAliasedInstall(deps),
        legacyInstall: detectLegacyInstall(cwd, deps),
    };
}
